import { useEffect, useState } from "react";
import axios from "axios";
import config from "../config";
import {
    Input,
    View,
    InputField,
    Box,
    Button,
    ButtonText,
    VStack,
    Heading,
    Text,
    FormControl,
    InputSlot,
    InputIcon,
    EyeIcon,
    EyeOffIcon,
    Center,
    AlertDialog,
    AlertDialogBackdrop,
    AlertDialogContent,
    AlertDialogHeader,
    AlertDialogCloseButton,
    AlertDialogBody,
    Icon,
    CloseIcon,
    AlertCircleIcon
} from "@gluestack-ui/themed";

import AsyncStorage from '@react-native-async-storage/async-storage';


import { useToast, Toast, ToastTitle, ToastDescription, Pressable, ButtonSpinner, AtSignIcon, LockIcon } from '@gluestack-ui/themed';

import * as Location from "expo-location"

import { ImageBackground } from '@gluestack-ui/themed';

import backgroundimg from '../assets/bg/2d-graphic-colorful-wallpaper-with-grainy-gradients.jpg'

import { Image } from "@gluestack-ui/themed"
import logo from '../assets/logo.png'


import { useIsFocused } from "@react-navigation/native";

import { useNavigation } from '@react-navigation/native';

const Login = ({ route }) => {

    const navigation = useNavigation();

    const focus = useIsFocused();

    const { setIsLoggedIn } = route.params;

    console.log(setIsLoggedIn);

    const [showPassword, setShowPassword] = useState(false);

    const [loginData, setLoginData] = useState({
        usercode: '',
        password: ''
    });

    const [location, setLocation] = useState({});

    const [locationalert, setlocationalert] = useState(false)

    const [loader, setloader] = useState(false)


    const handleState = () => {
        setShowPassword(!showPassword);
    };

    const toast = useToast()

    const handleSubmitLogin = async () => {
        const providerStatus = await Location.getProviderStatusAsync();
        if (!providerStatus.locationServicesEnabled) {
            setlocationalert(true);
            return;
        }

        if (loginData.usercode === '') {
            toast.show({
                placement: "top",
                render: ({ id }) => {
                    const toastId = "toast-" + id
                    return (

                        <Toast bg="$error700" nativeID={toastId}>
                            <Icon as={AlertCircleIcon} color="$white" mt="$1" mr="$3" />
                            <VStack space="xs">
                                <ToastTitle color="$textLight50">
                                    Enter UserCode
                                </ToastTitle>
                                <ToastDescription color="$textLight50">
                                    Please Enter User Code
                                </ToastDescription>
                            </VStack>
                            <Pressable mt="$1" onPress={() => toast.close(id)}>
                                <Icon as={CloseIcon} color="$coolGray50" />
                            </Pressable>
                        </Toast>
                    )
                },
            })

            return
        }

        if (loginData.password === '') {
            toast.show({
                placement: "top",
                render: ({ id }) => {
                    const toastId = "toast-" + id
                    return (
                        <Toast bg="$error700" nativeID={toastId}>
                            <Icon as={AlertCircleIcon} color="$white" mt="$1" mr="$3" />
                            <VStack space="xs">
                                <ToastTitle color="$textLight50">
                                    Enter Password
                                </ToastTitle>
                                <ToastDescription color="$textLight50">
                                    Please Enter Login Password
                                </ToastDescription>
                            </VStack>
                            <Pressable mt="$1" onPress={() => toast.close(id)}>
                                <Icon as={CloseIcon} color="$coolGray50" />
                            </Pressable>
                        </Toast>
                    )
                },
            })

            return
        }

        if (providerStatus.locationServicesEnabled) {
            const location = await Location.getCurrentPositionAsync({});
            await setLocation(location);
        }

        try {
            setloader(true)
            if (location && Object.keys(location).length !== 0) {

                const alldata = { ...loginData, location }
                const response = await axios.post(`${config.API_URL}/login`, alldata);

                if (response.status === 200) {
                    setloader(false);
              
                    if (response.data.Role === 'admin') {
                        console.log(response.data.Role === 'admin', 'admin');
                        navigation.navigate('DashBoard');
                    }
                    if (response.data.Role === 'user') {
                        console.log(response.data.Role === 'user', 'user');
                        navigation.navigate('Attendance');
                    }

                    const localstoragevalue = {
                        cmpid: response.data.companyId,
                        role: response.data.Role,
                        usercode: loginData.usercode
                    };
                    await AsyncStorage.setItem('userData', JSON.stringify(localstoragevalue));
                    setLocation({});
                    setLoginData({ ...loginData, usercode: '', password: '' });

                    //setIsLoggedIn(true);
                }

                if (response.status === 201) {
                    console.log(response.data)
                    setloader(false)
                    toast.show({
                        placement: "top",
                        render: ({ id }) => {
                            const toastId = "toast-" + id
                            return (
                                <Toast action="info" nativeID={toastId}>
                                    <Icon as={AlertCircleIcon} mt="$1" mr="$3" />
                                    <VStack space="xs">
                                        <ToastTitle >
                                            Range Alert
                                        </ToastTitle>
                                        <ToastDescription >
                                            Please go close to your company to login.
                                        </ToastDescription>
                                    </VStack>
                                    <Pressable mt="$1" onPress={() => toast.close(id)}>
                                        <Icon as={CloseIcon} />
                                    </Pressable>
                                </Toast>
                            )
                        },
                    })
                }

                if (response.status === 202) {

                    console.log(response.data)
                    setloader(false)

                    toast.show({
                        placement: "top",
                        render: ({ id }) => {
                            const toastId = "toast-" + id
                            return (
                                <Toast action="error" nativeID={toastId}>
                                    <Icon as={AlertCircleIcon} mt="$1" mr="$3" />
                                    <VStack space="xs">
                                        <ToastTitle >
                                            Your Not Found
                                        </ToastTitle>
                                        <ToastDescription >
                                            {response.data}
                                        </ToastDescription>
                                    </VStack>
                                    <Pressable mt="$1" onPress={() => toast.close(id)}>
                                        <Icon as={CloseIcon} />
                                    </Pressable>
                                </Toast>
                            )
                        },
                    })

                }
            } else {
                setloader(false)
                console.log("loacation data unavailable");
            }

        } catch (err) {
            console.error(err);
        }
    };

    useEffect(() => {
        if (focus === true) {
            (async () => {

                let { status } = await Location.requestForegroundPermissionsAsync();

                if (status !== 'granted') {
                    setlocationalert(true)
                    return;
                }
                else if (status === 'granted') {
                    let location = await Location.getCurrentPositionAsync({});
                    await setLocation(location);
                }

            })();
        }
    }, [focus])

    return (

        <>
            <ImageBackground source={backgroundimg}
                style={{ flex: 1, justifyContent: "center", backfaceVisibility: "visible" }} alt="background" h={"$full"}>

                <View style={{ flex: 1, justifyContent: 'center', alignItems: 'center' }} padding="$12" height={"$full"} >
                    <Box width="$96" borderWidth="$1" borderRadius="$lg" borderColor="$borderLight300" padding={"$10"}>
                        <FormControl $dark-borderWidth="$1" $dark-borderRadius="$lg" $dark-borderColor="$borderDark800">
                            <VStack space="xl">
                                {/* <Center>
                                    <Image size="sm" borderRadius="$lg" source={logo} alt="logo" />
                                </Center> */}


                                <Heading color="$white" lineHeight="$md" textAlign="center">
                                    Login
                                </Heading>
                                <VStack space="xs">
                                    <Text color="$white" lineHeight="$xs" marginBottom={"$1.5"}>
                                        Usercode
                                    </Text>
                                    <Input>
                                        <Icon as={AtSignIcon} m="$2" w="$4" h="$4" />
                                        <InputField type="text" color="$white" value={loginData.usercode} onChangeText={(e) => setLoginData({ ...loginData, usercode: e })} defaultValue={loginData.usercode} />
                                    </Input>
                                </VStack>

                                <VStack space="xs">
                                    <Text color="$white" lineHeight="$xs" marginBottom={"$1.5"}>
                                        Password
                                    </Text>
                                    <Input alignItems="center">
                                        <Icon as={LockIcon} m="$2" w="$4" h="$4" />
                                        <InputField color="$white" value={loginData.password} type={showPassword ? "text" : "password"} onChangeText={(e) => setLoginData({ ...loginData, password: e })} defaultValue={loginData.password} />
                                        <InputSlot pr="$3" onPress={handleState}>
                                            <InputIcon as={showPassword ? EyeIcon : EyeOffIcon} color="$white" />
                                        </InputSlot>
                                    </Input>
                                </VStack>
                                <Center>

                                    <Button onPress={handleSubmitLogin} width={"$full"} style={{ display: loader === true ? "none" : "flex" }} disabled={loader === true}>
                                        <ButtonText color="$white">Login</ButtonText>
                                    </Button>


                                    <Button isDisabled={true} bg='$darkBlue600' width={"$full"} p='$3' style={{ display: loader === true ? "flex" : "none" }}>
                                        <ButtonSpinner mr='$1' />
                                        <ButtonText fontWeight='$medium' fontSize="$sm">Please wait...</ButtonText>
                                    </Button>


                                </Center>
                            </VStack>
                        </FormControl>
                    </Box>

                    <AlertDialog
                        isOpen={locationalert}
                        onClose={() => setlocationalert(false)}
                    >
                        <AlertDialogBackdrop />
                        <AlertDialogContent backgroundColor="$error700" >
                            <AlertDialogHeader>
                                <Heading size="md" color="$white" >Location Enable</Heading>
                                <AlertDialogCloseButton>
                                    <Icon as={CloseIcon} color="$white" />
                                </AlertDialogCloseButton>
                            </AlertDialogHeader>
                            <AlertDialogBody height="$48" padding={"$10"}>
                                <Center>
                                    <Icon as={AlertCircleIcon} m="$2" w="$11" h="$11" color="$white" />
                                    <Text size="2xl" color="$white" mt="$1.5">
                                        Please Enable Location Then Login
                                    </Text>
                                </Center>

                            </AlertDialogBody>
                        </AlertDialogContent>
                    </AlertDialog>





                </View >
            </ImageBackground >
        </>
    );
};

export default Login;
