import { Box, Button, ButtonText, View, Input, InputField, ScrollView } from '@gluestack-ui/themed';
import * as React from 'react';
import { DataTable } from 'react-native-paper';
import { useState, createElement } from 'react';
import { Platform, StyleSheet } from 'react-native';
import DateTimePicker from '@react-native-community/datetimepicker';
import axios from 'axios';

import { SelectList } from 'react-native-dropdown-select-list'
import config from '../config';

import { ImageBackground } from '@gluestack-ui/themed';

import backgroundimg from '../assets/bg/2d-graphic-colorful-wallpaper-with-grainy-gradients.jpg'

const Report = () => {
    const [page, setPage] = React.useState(1);
    const [numberOfItemsPerPageList] = React.useState([2, 3, 4]);

    const [itemsPerPage, onItemsPerPageChange] = React.useState(numberOfItemsPerPageList[2]);



    const [items] = React.useState([
        {
            key: 1,
            name: 'Cupcake',
            calories: 356,
            fat: 16,
            amount: 500,
        },
        {
            key: 2,
            name: 'Eclair',
            calories: 262,
            fat: 16,
            amount: 500,
        },
        {
            key: 3,
            name: 'Frozen yogurt',
            calories: 159,
            fat: 6,
            amount: 500,
        },
        {
            key: 4,
            name: 'Gingerbread',
            calories: 305,
            fat: 3.7,
            amount: 500,
        },
    ]);

    const from = page * itemsPerPage;
    const to = Math.min((page + 1) * itemsPerPage, items.length);

    React.useEffect(() => {
        setPage(0);
    }, [itemsPerPage]);


    const [showFromDatePicker, setShowFromDatePicker] = useState(false);

    const [showToDatePicker, setShowToDatePicker] = useState(false);

    const [fromDate, setFromDate] = useState(new Date());

    const [toDate, setToDate] = useState(new Date());

    const [modeData, setmodeData] = useState({
        selectmode: "",
        usercode: ''
    })


    const handleFromDateChange = (event, selectedDate) => {

        console.log(event, selectedDate);
        const currentDate = selectedDate || fromDate;
        setShowFromDatePicker(Platform.OS === 'ios');
        setFromDate(currentDate);
    };

    const handleToDateChange = (event, selectedDate) => {

        console.log(event, selectedDate);

        const currentDate = selectedDate || toDate;
        setShowToDatePicker(Platform.OS === 'ios');
        setToDate(currentDate);
    };






    function FromDatePicker({ value, onChange }) {
        return (
            <input
                type="date"
                value={value}
                onChange={(e) => setFromDate(e.target.value)}
                style={style.Datepicker}
            />
        );
    }

    function ToDatePicker({ value, onChange }) {
        return (
            <input
                type="date"
                value={value}
                onChange={(e) => setToDate(e.target.value)}
                style={style.Datepicker}
            />
        );
    }

    const renderFromDatePicker = () => {
        if (Platform.OS === 'web') {
            return (
                <FromDatePicker value={fromDate} />
            );
        } else {
            return (
                <DateTimePicker
                    testID="fromDatePicker"
                    value={fromDate}
                    mode="date"
                    display="default"
                    onChange={handleFromDateChange}
                />
            );
        }
    };

    const renderToDatePicker = () => {
        if (Platform.OS === 'web') {
            return (
                <ToDatePicker value={toDate} />
            );
        } else {
            return (
                <DateTimePicker
                    testID="toDatePicker"
                    value={toDate}
                    mode="date"
                    display="default"
                    onChange={handleToDateChange}
                />
            );
        }
    };


    const [reportData, setreportData] = useState([])

    const data = [
        { key: '1', value: 'all', },
        { key: '2', value: 'individual' },
    ]

    const serachreport = async () => {

        try {

            const device = Platform.OS

            const mode = modeData.selectmode

            const usercode = modeData.usercode

            const alldata = { fromDate, toDate, device, mode, usercode }

            const response = await axios.get(`${config.API_URL}/attendance_report`, {
                params: alldata
            })


            if (response.data) {

                console.log(response);
                setreportData(response.data)
            }


        } catch (err) {
            console.log(err);
        }


    }


    return (
        <>
        <ImageBackground source={backgroundimg}
                style={{ flex: 1, justifyContent: "center", backfaceVisibility: "visible" }} alt="background" h={"$full"}>
            <View height={"$full"} w="$full">
                <View style={{ flex: 1, justifyContent: "flex-start", alignItems: "center" }}  >

                    <Box alignItems="center" width="$96" borderWidth="$1" borderRadius="$lg" 
                        padding={"$10"} mt="$5"  $lg-w="$5/6" $lg-display="flex" $lg-flexDirection='row' height="$5/6" $lg-height="$2/5">


                        <View $lg-marginRight="$10">
                            <Button bg='$coolGray900' onPress={() => setShowFromDatePicker(prevState => !prevState)}>
                                <ButtonText>
                                    From Date
                                </ButtonText>
                            </Button>

                        </View>

                        <View mt="$4" $lg-mt="$0" $lg-marginRight="$10">
                            <Button bg='$coolGray900' onPress={() => setShowToDatePicker(prevState => !prevState)}>
                                <ButtonText >
                                    To Date
                                </ButtonText>
                            </Button>
                        </View>


                        <View mt="$4" $lg-mt="$0">
                            <SelectList
                                setSelected={(val) => setmodeData({ ...modeData, selectmode: val })}
                                data={data}
                                save="value"
                                inputStyles={style.inputStyles}
                                dropdownTextStyles={style.dropdownTextStyles}
                                dropdownItemStyles={style.dropdownItemStyles}
                                boxStyles={style.boxStyles}
                            />
                        </View>

                        <View mt="$4" style={{ display: modeData.selectmode === 'individual' ? "flex" : "none" }} w="$56" $lg-mt="$0" $lg-marginRight="$10">
                            <Input variant="outline" size="md" >
                                <InputField
                                    placeholder='Enter User Code'
                                    onChangeText={(e) => setmodeData({ ...modeData, usercode: e })}
                                />
                            </Input>
                        </View>


                        <View mt="$4" $lg-mt="$0" $lg-marginLeft="$10">
                            <Button action="primary" onPress={() => serachreport()}>
                                <ButtonText>
                                    Search
                                </ButtonText>
                            </Button>
                        </View>


                    </Box>
                    {showFromDatePicker && renderFromDatePicker()}
                    {showToDatePicker && renderToDatePicker()}
                </View>

                <View mt="$0">

                    <ScrollView>

                        <DataTable style={{ backgroundColor: "white", borderWidth: 2, borderColor: "black" }} >
                            <DataTable.Header style={style.DataTable_Header}>
                                <DataTable.Title textStyle={style.DataTable_Header}>companyname</DataTable.Title>
                                {/* <DataTable.Title numeric>usercode</DataTable.Title> */}
                                <DataTable.Title textStyle={style.DataTable_Header} >username</DataTable.Title>
                                <DataTable.Title textStyle={style.DataTable_Header}>intime</DataTable.Title>
                                <DataTable.Title textStyle={style.DataTable_Header}>outtime</DataTable.Title>
                            </DataTable.Header>

                            {reportData.slice(from, to).map((item) => (
                                <DataTable.Row key={item.Sno}>
                                    <DataTable.Cell textStyle={style.DataTable_Data}>{item.companyname}</DataTable.Cell>
                                    {/* <DataTable.Cell numeric>{item.usercode}</DataTable.Cell> */}
                                    <DataTable.Cell textStyle={style.DataTable_Data}>{item.username}</DataTable.Cell>
                                    <DataTable.Cell textStyle={style.DataTable_Data}>{item.intime}</DataTable.Cell>
                                    <DataTable.Cell textStyle={style.DataTable_Data}>{item.outtime}</DataTable.Cell>
                                </DataTable.Row>
                            ))}

                            <DataTable.Pagination
                                page={page}
                                numberOfPages={Math.ceil(items.length / itemsPerPage)}
                                onPageChange={(page) => setPage(page)}
                                label={`${from + 1}-${to} of ${items.length}`}
                                //numberOfItemsPerPageList={numberOfItemsPerPageList}
                                numberOfItemsPerPage={itemsPerPage}
                                onItemsPerPageChange={onItemsPerPageChange}
                                showFastPaginationControls
                                selectPageDropdownLabel={'Rows per page'}
                            />
                        </DataTable>

                    </ScrollView>

                </View>

            </View>
        </ImageBackground >
        </>
    );
};

export default Report;


const style = StyleSheet.create({

    Datepicker: {

        height: "auto",
        width: 100,
        padding: 20,
        borderRadius: 5,
        display: "flex",
        flexDirection: "row"

    },
    DropDown: {
        backgroundColor: "white",
        color: "black"
    },
    dropdownTextStyles: {
        backgroundColor: "white",
        color: "black"
    },
    dropdownItemStyles: {
        backgroundColor: "white",
        color: "black",

    },
    boxStyles: {
        backgroundColor: "white",
        color: "black",
        width: 250
    },
    DataTable_Header: {
        fontFamily: "Inter_500Medium",
        backgroundColor: "lightgray",
        textTransform: "uppercase",
        textAlign: "justify",
        fontSize: 14,
        color: "black",
        paddingRight: 5,


    },
    DataTable_Data: {
        fontFamily: "Inter_500Medium",
        color: "gray",
        fontSize: 13,
        textAlign: "justify",

    }
})