import { Text, View, Card, Heading, Button, ButtonText, ButtonGroup } from "@gluestack-ui/themed"
import { useEffect, useState } from "react"
import AsyncStorage from '@react-native-async-storage/async-storage';
import axios from "axios";
import config from "../config";
import { useIsFocused } from "@react-navigation/native";

import {
    AlertDialog,
    AlertDialogBackdrop,
    AlertDialogContent,
    AlertDialogHeader,
    AlertDialogCloseButton,
    AlertDialogFooter,
    AlertDialogBody,
    Icon,
    CloseIcon,
    CheckCircleIcon
} from "@gluestack-ui/themed"

import { useToast, Toast, ToastTitle, ToastDescription, Pressable, ButtonSpinner, VStack } from '@gluestack-ui/themed';
import { ImageBackground } from '@gluestack-ui/themed';

import backgroundimg from '../assets/bg/2d-graphic-colorful-wallpaper-with-grainy-gradients.jpg'


const Attendance = () => {

    const focus = useIsFocused();

    const [showAlertDialog, setShowAlertDialog] = useState(false)

    const [ShowalertStatus, SetShowalertStatus] = useState('')

    const [userdata, setuserdata] = useState([])

    const [companydata, setcompanydata] = useState([])

    const [loader, setloader] = useState(false)

    const [attendanceTime, setattendanceTime] = useState({
        intime: '',
        outtime: ''
    })


    const [intimtStatus, SetintimeStatus] = useState([])


    const toast = useToast()


    const attendancein = async () => {

        setShowAlertDialog(true)

        SetShowalertStatus('checkin')

    }

    const CheckinConfirm = async () => {

        console.log("check in");

        setloader(true)

        try {
            const currentDate = new Date();
            const year = currentDate.getFullYear();
            const month = String(currentDate.getMonth() + 1).padStart(2, '0');
            const day = String(currentDate.getDate()).padStart(2, '0');
            const hours = String(currentDate.getHours()).padStart(2, '0');
            const minutes = String(currentDate.getMinutes()).padStart(2, '0');
            const seconds = String(currentDate.getSeconds()).padStart(2, '0');

            const intime = `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;

            console.log(intime);

            const usercode = await userdata?.usercode

            console.log(usercode);

            const alldata = { usercode, intime, Outtime: null }

            const response = await axios.put(`${config.API_URL}/Checkin-CheckOut`, alldata)

            if (response.data) {

                SetShowalertStatus('')

                console.log(response.data);
                toast.show({
                    placement: "top",
                    render: ({ id }) => {
                        const toastId = "toast-" + id
                        return (
                            <Toast action="success" nativeID={toastId}>
                                <Icon as={CheckCircleIcon} mt="$1" mr="$3" />
                                <VStack space="xs">
                                    <ToastTitle >
                                        Check In Success
                                    </ToastTitle>
                                    <ToastDescription >
                                        Thank you for your submission. Your Check In Success
                                    </ToastDescription>
                                </VStack>
                                <Pressable mt="$1" onPress={() => toast.close(id)}>
                                    <Icon as={CloseIcon} />
                                </Pressable>
                            </Toast>
                        )
                    },
                })
                setloader(false)
            }


        } catch (err) {
            console.log(err);
            setloader(false)
        }
    }

    const attendanceout = async () => {
        setShowAlertDialog(true)
    }

    const CheckOutConfirm = async () => {

        try {
            const currentDate = new Date();
            const year = currentDate.getFullYear();
            const month = String(currentDate.getMonth() + 1).padStart(2, '0');
            const day = String(currentDate.getDate()).padStart(2, '0');
            const hours = String(currentDate.getHours()).padStart(2, '0');
            const minutes = String(currentDate.getMinutes()).padStart(2, '0');
            const seconds = String(currentDate.getSeconds()).padStart(2, '0');

            const Outtime = `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;

            console.log(Outtime);

            const usercode = await userdata?.usercode

            console.log(usercode);

            const alldata = { usercode, Outtime, intime: null }

            const response = await axios.put(`${config.API_URL}/Checkin-CheckOut`, alldata)

            if (response.data) {

                SetShowalertStatus('')

                console.log(response.data);
                toast.show({
                    placement: "top",
                    render: ({ id }) => {
                        const toastId = "toast-" + id
                        return (
                            <Toast action="success" nativeID={toastId}>
                                <Icon as={CheckCircleIcon} mt="$1" mr="$3" />
                                <VStack space="xs">
                                    <ToastTitle >
                                        Check OUT Success
                                    </ToastTitle>
                                    <ToastDescription >
                                        Thank you for your submission. Your Check OUT Success
                                    </ToastDescription>
                                </VStack>
                                <Pressable mt="$1" onPress={() => toast.close(id)}>
                                    <Icon as={CloseIcon} />
                                </Pressable>
                            </Toast>
                        )
                    },
                })
                setloader(false)
            }

        } catch (err) {
            console.log(err);
        }


    }




    const getdbdata = async () => {
        try {
            const id = await userdata?.cmpid
            await axios.get(`${config.API_URL}/company_name/${id}`)
                .then((res) => {
                    setcompanydata(res.data)
                })
                .catch((err) => {
                    console.log(err);
                })

        } catch (err) {

            console.log(err);

        }



    }

    const CompanyNameGEt = async () => {        /// local storage data get

        async function fetchData() {
            const getuserdata = await AsyncStorage.getItem('userData');
            setuserdata(JSON.parse(getuserdata));
        }

        fetchData()

    }



    const IntimeOutimeBtn_status = async () => {

        try {

            const usercode = await userdata?.usercode

            const intimeRequest = await axios.get(`${config.API_URL}/intimeStatus?usercode=${usercode}`)

            if (intimeRequest.data) {
                SetintimeStatus(intimeRequest.data)

                const { count, intime_date, outtime_date } = intimeRequest.data[0]

                setattendanceTime({ ...attendanceTime, intime: intime_date, outtime: outtime_date })

                console.log(count, intime_date, outtime_date);
            }

        } catch (err) {

        }

    }


    useEffect(() => {

        if (userdata && userdata.length !== 0) {
            IntimeOutimeBtn_status();
            getdbdata();
        }


    }, [userdata]);

    useEffect(() => {

        if (focus === true) {

            // initial page load data
            // IntimeOutimeBtn_status();
            CompanyNameGEt()
            // Function to be executed every 10 seconds
            const intervalLoop = () => {
                //    IntimeOutimeBtn_status();
                CompanyNameGEt()

            };

            const intervalId = setInterval(intervalLoop, 1000);

            // Clean up the interval when the component is unmounted
            return () => {
                //     IntimeOutimeBtn_status();
                CompanyNameGEt()


                clearInterval(intervalId);
            };
        }
    }, [focus]);


    return (
        <>

            <ImageBackground source={backgroundimg}
                style={{ flex: 1, justifyContent: "center", backfaceVisibility: "visible" }} alt="background" h={"$full"}>

                <View style={{ flex: 1, alignContent: 'center', justifyContent: 'center', }} padding="0" height={"$full"}  w="$full" $lg-display="flex" $lg-justifyContent="center" $lg-alignItems="center">

                    <Card size="lg" variant="filled" m={"$3"} $lg-w={"$1/3"} >
                        <Heading mb="$10" size="mg" textAlign="center">
                            <Text fontFamily="Inter_700Bold" fontSize={20}>Live Attendance</Text>
                        </Heading >

                        <View style={{ display: 'flex', flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', width: '100%' }} flexWrap="wrap" >

                            <View mb="$5" >
                                <Text size="md" p="$1.5" fontFamily="Inter_500Medium">CompanyName :
                                    <Text fontFamily="Inter_500Medium" >{companydata[0]?.companyname}</Text>
                                </Text>
                            </View>
                            <View mb="$5">
                                <Text size="md" p="$1.5" fontFamily="Inter_500Medium">UserCode :
                                    <Text fontFamily="Inter_500Medium" > {userdata?.usercode}</Text>
                                </Text>
                            </View>

                            <View mb="$5">
                                <Text size="md" p="$1.5" fontFamily="Inter_500Medium" >Date :
                                    <Text fontFamily="Inter_500Medium" >
                                        {new Date().toLocaleDateString()}
                                    </Text>
                                </Text>
                            </View>
                            <View mb="$5">
                                <Text size="md" p="$1.5" fontFamily="Inter_500Medium">Attendance In :
                                    <Text fontFamily="Inter_500Medium">
                                        {attendanceTime.intime && new Date(attendanceTime.intime).toISOString().replace('T', ' ').replaceAll('/', '-').slice(0, 19)}
                                    </Text>

                                </Text>
                            </View>
                        </View>



                        <Button mt="$1.5" onPress={attendancein} style={{ display: loader === true ? "none" : "flex" }} action="positive" disabled={intimtStatus.length !== 0}>
                            <ButtonText fontFamily="Inter_500Medium">Check In</ButtonText>
                        </Button>

                        <Button isDisabled={true} bg='$darkBlue600' width={"$full"} p='$3' style={{ display: loader === true ? "flex" : "none" }}>
                            <ButtonSpinner mr='$1' />
                            <ButtonText fontFamily="Inter_500Medium" >Please wait...</ButtonText>
                        </Button>


                        <Button mt="$1.5" onPress={attendanceout} style={{ display: loader === true || intimtStatus.length === 0 ? "none" : "flex" }} variant="solid" action="negative" marginTop="$3"
                            disabled={attendanceTime.outtime !== null}>
                            <ButtonText fontFamily="Inter_500Medium">Check Out</ButtonText>
                        </Button>


                        {attendanceTime.outtime !== null && intimtStatus.length !== 0 &&
                            (
                                <Text style={{ display: attendanceTime.outtime !== null && intimtStatus.length !== 0 ? "flex" : "none" }} fontFamily="Inter_500Medium" textAlign="center" mt={"$4"} $lg-alignItems="center" $lg-justifyContent="center">
                                    Your Today Attendance As Done
                                </Text>
                            )
                        }


                    </Card>




                    <AlertDialog
                        isOpen={showAlertDialog}
                        onClose={() => {
                            setShowAlertDialog(false)
                        }}
                    >
                        <AlertDialogBackdrop />
                        <AlertDialogContent>
                            <AlertDialogHeader>
                                <Heading size="lg" fontFamily="Inter_700Bold">{ShowalertStatus === 'checkin' ? 'Check In' : 'Check Out'}</Heading>
                                <AlertDialogCloseButton>
                                    <Icon as={CloseIcon} />
                                </AlertDialogCloseButton>
                            </AlertDialogHeader>
                            <AlertDialogBody>
                                <Text size="sm" fontFamily="Inter_700Bold" >
                                    {ShowalertStatus === 'checkin' ? 'Are You Sure Check In Attendance' : 'Are You Sure Check Out Attendance'}
                                </Text>
                            </AlertDialogBody>
                            <AlertDialogFooter>
                                <ButtonGroup space="lg">
                                    <Button
                                        variant="outline"
                                        action="secondary"
                                        onPress={() => {
                                            setShowAlertDialog(false)
                                        }}
                                    >
                                        <ButtonText fontFamily="Inter_400Regular" >Cancel</ButtonText>
                                    </Button>
                                    <Button
                                        action="positive"
                                        onPress={() => {
                                            ShowalertStatus === 'checkin' ? CheckinConfirm() : CheckOutConfirm()
                                            setShowAlertDialog(false)
                                        }}
                                    >
                                        <ButtonText fontFamily="Inter_900Black">{ShowalertStatus === 'checkin' ? 'Check In' : 'Check Out'}</ButtonText>
                                    </Button>
                                </ButtonGroup>
                            </AlertDialogFooter>
                        </AlertDialogContent>
                    </AlertDialog>
                </View>
            </ImageBackground >
        </>
    )

}

export default Attendance

