import { View, Box, VStack, Input, InputField, FormControl, FormControlLabel, FormControlLabelText, Button, ButtonText, ScrollView, Center } from "@gluestack-ui/themed";
import { useEffect, useState, useRef } from "react";
import {
    AlertDialog,
    AlertDialogBackdrop,
    AlertDialogContent,
    AlertDialogHeader,
    AlertDialogCloseButton,
    AlertDialogFooter,
    AlertDialogBody,
    Icon,
    CloseIcon,
    CheckCircleIcon,
    Heading,
    Text,
    ButtonGroup
} from "@gluestack-ui/themed"
import { useToast, Toast, ToastTitle, ToastDescription, Pressable, ButtonSpinner, AlertCircleIcon, CheckIcon } from '@gluestack-ui/themed';
import axios from "axios";
import config from "../config";
import { useIsFocused } from "@react-navigation/native";


import { Modal, ModalBackdrop, ModalContent, ModalHeader, ModalCloseButton, ModalBody, ModalFooter } from '@gluestack-ui/themed';

import { StyleSheet, FlatList } from "react-native";

import Spinner from 'react-native-loading-spinner-overlay'


import { ImageBackground } from '@gluestack-ui/themed';

import backgroundimg from '../assets/bg/2d-graphic-colorful-wallpaper-with-grainy-gradients.jpg'


const CompanyMaster = () => {


    const toast = useToast()
    const focus = useIsFocused();


    const [userdata, setuserdata] = useState({
        companyname: "",
        latitude: "",
        longitude: ""
    })


    const [Updateuserdata, SetUpdateuserdata] = useState({
        companyname: "",
        latitude: "",
        longitude: ""
    })
    const [validation, Setvalidation] = useState([])

    const [loader, setloader] = useState(false)

    const [spinner, setspinner] = useState(false)


    const [showAlertDialog, setShowAlertDialog] = useState(false)

    const [showAlterStatus, SetshowAlterStatus] = useState('')

    const createcompany = () => {
        if (userdata.companyname === '') {
            toast.show({
                placement: "top",
                render: ({ id }) => {
                    const toastId = "toast-" + id
                    return (
                        <Toast bg="$error500" nativeID={toastId}>
                            <Icon as={AlertCircleIcon} color="$white" mt="$1" mr="$3" />
                            <VStack space="xs">
                                <ToastTitle color="$textLight50" fontFamily="Inter_500Medium">
                                    Company Name Empty
                                </ToastTitle>
                                <ToastDescription color="$textLight50" fontFamily="Inter_500Medium">
                                    Please Fill The Valid Company Name
                                </ToastDescription>
                            </VStack>
                            <Pressable mt="$1" onPress={() => toast.close(id)}>
                                <Icon as={CloseIcon} color="$coolGray50" />
                            </Pressable>
                        </Toast>
                    )
                },
            })
            return
        }

        if (userdata.latitude === '') {
            toast.show({
                placement: "top",
                render: ({ id }) => {
                    const toastId = "toast-" + id
                    return (
                        <Toast bg="$error500" nativeID={toastId}>
                            <Icon as={AlertCircleIcon} color="$white" mt="$1" mr="$3" />
                            <VStack space="xs">
                                <ToastTitle color="$textLight50" fontFamily="Inter_500Medium">
                                    Latitude Empty
                                </ToastTitle>
                                <ToastDescription color="$textLight50" fontFamily="Inter_500Medium">
                                    Please Fill The Valid Latitude
                                </ToastDescription>
                            </VStack>
                            <Pressable mt="$1" onPress={() => toast.close(id)}>
                                <Icon as={CloseIcon} color="$coolGray50" />
                            </Pressable>
                        </Toast>
                    )
                },
            })
            return
        }


        if (userdata.longitude === '') {
            toast.show({
                placement: "top",
                render: ({ id }) => {
                    const toastId = "toast-" + id
                    return (
                        <Toast bg="$error500" nativeID={toastId}>
                            <Icon as={AlertCircleIcon} color="$white" mt="$1" mr="$3" />
                            <VStack space="xs">
                                <ToastTitle color="$textLight50">
                                    Longitude Password
                                </ToastTitle>
                                <ToastDescription color="$textLight50">
                                    Please Fill The Valid Longitude
                                </ToastDescription>
                            </VStack>
                            <Pressable mt="$1" onPress={() => toast.close(id)}>
                                <Icon as={CloseIcon} color="$coolGray50" />
                            </Pressable>
                        </Toast>
                    )
                },
            })
            return
        }



        const Isuserexits = validation.some(items =>
            userdata.companyname === items.companyname &&
            userdata.latitude === items.cmp_latitude &&
            userdata.longitude === items.cmp_longitude
        );

        if (Isuserexits) {
            toast.show({
                placement: "top",
                render: ({ id }) => {
                    const toastId = "toast-" + id
                    return (
                        <Toast bg="$error500" nativeID={toastId}>
                            <Icon as={AlertCircleIcon} color="$white" mt="$1" mr="$3" />
                            <VStack space="xs">
                                <ToastTitle color="$textLight50" fontFamily="Inter_500Medium">
                                    Company Existing
                                </ToastTitle>
                                <ToastDescription color="$textLight50" fontFamily="Inter_500Medium">
                                    This Company Master Is already Presented. . !
                                </ToastDescription>
                            </VStack>
                            <Pressable mt="$1" onPress={() => toast.close(id)}>
                                <Icon as={CloseIcon} color="$coolGray50" />
                            </Pressable>
                        </Toast>
                    )
                },
            })
            return

        }

        SetshowAlterStatus('create')

        setShowAlertDialog(true)
    }

    const confirmCreateaccount = async () => {

        try {

            setloader(true)

            const response = await axios.post(`${config.API_URL}/Company-register`, userdata)

            if (response.data) {
                fetchdata()
                setuserdata({ ...userdata, companyname: '', latitude: '', longitude: '' })
                toast.show({
                    placement: "top",
                    render: ({ id }) => {
                        const toastId = "toast-" + id
                        return (
                            <Toast bg="$success700" nativeID={toastId}>
                                <Icon as={CheckIcon} color="$white" mt="$1" mr="$3" />
                                <VStack space="xs">
                                    <ToastTitle color="$textLight50" fontFamily="Inter_500Medium">
                                        Created Successs
                                    </ToastTitle>
                                    <ToastDescription color="$textLight50" fontFamily="Inter_500Medium">
                                        Comapany Created SuccessFully..!
                                    </ToastDescription>
                                </VStack>
                                <Pressable mt="$1" onPress={() => toast.close(id)}>
                                    <Icon as={CloseIcon} color="$coolGray50" />
                                </Pressable>
                            </Toast>
                        )
                    },
                })


                setloader(false)
            }

        } catch (err) {
            console.log(err)
            setloader(false)
        }
    }


    const fetchdata = async () => {
        setspinner(true)
        const response = await axios.get(`${config.API_URL}/get-companydata`)
        if (response.data) {
            Setvalidation(response.data)
            setspinner(false)
        }
    }


    const [openUpdateMoadl, SetopenUpdateMoadl] = useState(false)

    const ref = useRef(null)


    const rednerTableItem = ({ item, index }) => {
        return (
            <View style={styles.row}>

                <Text style={[styles.cell, { width: 45 }]} >{index + 1}</Text>
                <Text style={[styles.cell, { width: 150, textAlign: "center" }]}>{item.companyname}</Text>
                <Text style={[styles.cell, { width: 150, textAlign: "center" }]} ml={"$10"}>{item.cmp_latitude}</Text>
                <Text style={[styles.cell, { width: 150, textAlign: "center" }]} >{item.cmp_longitude}</Text>

                <Button style={[styles.cell, { width: 150, margin: 2, textAlign: "center", marginLeft: 5 }]} onPress={() => hanldeupdate(item.id)} ref={ref}>
                    <ButtonText>Edit</ButtonText>
                </Button>

                <Button style={[styles.cell, { width: 150, margin: 2, textAlign: "center", marginLeft: 15 }]} bg="$error500" onPress={() => hanldedelete(item.id)}>
                    <ButtonText>Delete</ButtonText>
                </Button>

            </View >

        )
    }

    const [id, setid] = useState('')

    const hanldeupdate = (id) => {
        setid(id)
        SetshowAlterStatus('update')
        SetopenUpdateMoadl(true)
        editdata(id)
        setspinner(true)
    }

    const editdata = async (id) => {
        const respose = await axios.get(`${config.API_URL}/edit-companydata/` + id)
        if (respose.data) {
            const { id, companyname, cmp_latitude, cmp_longitude } = respose.data[0]
            SetUpdateuserdata({ ...Updateuserdata, companyname: companyname, latitude: cmp_latitude, longitude: cmp_longitude })
            setspinner(false)
        }

    }

    const confirmUpdate = async () => {

        try {
            const resposnse = await axios.put(`${config.API_URL}/update-companydata/${id}`, Updateuserdata)

            if (resposnse.status === 200) {
                fetchdata()
                return (
                    toast.show({
                        placement: "top",
                        render: ({ id }) => {
                            const toastId = "toast-" + id
                            return (
                                <Toast bg="$success700" nativeID={toastId}>
                                    <Icon as={CheckIcon} color="$white" mt="$1" mr="$3" />
                                    <VStack space="xs">
                                        <ToastTitle color="$textLight50" fontFamily="Inter_500Medium">
                                            Updated Successs
                                        </ToastTitle>
                                        <ToastDescription color="$textLight50" fontFamily="Inter_500Medium">
                                            Your Data Updated Succesfully...!
                                        </ToastDescription>
                                    </VStack>
                                    <Pressable mt="$1" onPress={() => toast.close(id)}>
                                        <Icon as={CloseIcon} color="$coolGray50" />
                                    </Pressable>
                                </Toast>
                            )
                        },
                    })
                )
            }

        } catch (err) {
            console.log(err);
        }

    }

    const hanldedelete = async (id) => {

        try {

            const response = await axios.delete(`${config.API_URL}/delete-company/${id}`)

            if (response.status === 200) {
                fetchdata()
                return (
                    toast.show({
                        placement: "top",
                        render: ({ id }) => {
                            const toastId = "toast-" + id
                            return (
                                <Toast bg="$success700" nativeID={toastId}>
                                    <Icon as={CheckIcon} color="$white" mt="$1" mr="$3" />
                                    <VStack space="xs">
                                        <ToastTitle color="$textLight50" fontFamily="Inter_500Medium">
                                            Delete Successs
                                        </ToastTitle>
                                        <ToastDescription color="$textLight50" fontFamily="Inter_500Medium">
                                            Your Data Delete Succesfully...!
                                        </ToastDescription>
                                    </VStack>
                                    <Pressable mt="$1" onPress={() => toast.close(id)}>
                                        <Icon as={CloseIcon} color="$coolGray50" />
                                    </Pressable>
                                </Toast>
                            )
                        },
                    })
                )
            }

        } catch (err) {
            console.log(err);
        }

    }

    useEffect(() => {
        if (focus === true) {
            fetchdata()
        }
    }, [focus])
    return (
        <>

            <View h={"$full"} w={"$full"} >

                <ImageBackground source={backgroundimg}
                    style={{ width: '100%', height: '100%', justifyContent: "center", backfaceVisibility: "visible", resizeMode: "cover" }} alt="background">

                    <View $lg-display="flex" $lg-justifyContent="flex-start" $lg-alignItems="center">

                        <Box h="$96" justifyContent="center" borderWidth={1} borderRadius={"$lg"} $lg-w={"$1/3"} marginTop={"$10"}>
                            <VStack space="lg" reversed={false} alignItems="center" $lg-p={"$2"}>

                                <View>
                                    <Text fontFamily="Inter_500Medium" fontSize="$xl">Mapping Company</Text>
                                </View>

                                <View >
                                    <FormControl minWidth='$80'>
                                        <FormControlLabel>
                                            <FormControlLabelText fontFamily="Inter_500Medium">
                                                Company Name
                                            </FormControlLabelText>
                                        </FormControlLabel>
                                        <Input >
                                            <InputField value={userdata.companyname} defaultValue={userdata.companyname} onChangeText={(e) => setuserdata({ ...userdata, companyname: e })} />
                                        </Input>
                                    </FormControl>


                                    <FormControl minWidth='$80' mt="$4">
                                        <FormControlLabel>
                                            <FormControlLabelText fontFamily="Inter_500Medium">
                                                Latitude
                                            </FormControlLabelText>
                                        </FormControlLabel>
                                        <Input>
                                            <InputField value={userdata.latitude} defaultValue={userdata.latitude} onChangeText={(e) => setuserdata({ ...userdata, latitude: e })} />
                                        </Input>
                                    </FormControl>

                                    <FormControl minWidth='$80' mt="$4">
                                        <FormControlLabel>
                                            <FormControlLabelText fontFamily="Inter_500Medium" >
                                                Longitude
                                            </FormControlLabelText>
                                        </FormControlLabel>
                                        <Input>
                                            <InputField value={userdata.longitude} defaultValue={userdata.longitude} onChangeText={(e) => setuserdata({ ...userdata, longitude: e })} />
                                        </Input>
                                    </FormControl>

                                    <FormControl mt="$6">
                                        <Button bg="$darkBlue600" onPress={createcompany} style={{ display: loader === true ? "none" : "flex" }}>
                                            <ButtonText fontSize="$sm" fontWeight="$medium" fontFamily="Inter_500Medium">
                                                Create Company
                                            </ButtonText>
                                        </Button>

                                        <Button isDisabled={true} bg='$darkBlue600' width={"$full"} p='$3' style={{ display: loader === true ? "flex" : "none" }}>
                                            <ButtonSpinner mr='$1' />
                                            <ButtonText fontWeight='$medium' fontSize="$sm" fontFamily="Inter_500Medium">Please wait...</ButtonText>
                                        </Button>

                                    </FormControl>


                                </View>

                            </VStack>
                        </Box>

                        <AlertDialog
                            isOpen={showAlertDialog}
                            onClose={() => {
                                setShowAlertDialog(false)
                            }}
                        >
                            <AlertDialogBackdrop />
                            <AlertDialogContent>
                                <AlertDialogHeader>
                                    <Heading size="lg" fontFamily="Inter_500Medium">Create Company</Heading>
                                    <AlertDialogCloseButton>
                                        <Icon as={CloseIcon} />
                                    </AlertDialogCloseButton>
                                </AlertDialogHeader>
                                <AlertDialogBody>
                                    <Text size="sm" fontFamily="Inter_500Medium">
                                        Are you sure you want to Create This Comapny
                                    </Text>
                                </AlertDialogBody>
                                <AlertDialogFooter>
                                    <ButtonGroup space="lg">
                                        <Button
                                            variant="outline"
                                            action="secondary"
                                            onPress={() => {
                                                setShowAlertDialog(false)
                                            }}
                                        >
                                            <ButtonText fontFamily="Inter_500Medium">Cancel</ButtonText>
                                        </Button>
                                        <Button
                                            bg="$error600"
                                            action="negative"
                                            onPress={() => {
                                                confirmCreateaccount()
                                                setShowAlertDialog(false)

                                            }}
                                        >
                                            <ButtonText fontFamily="Inter_500Medium">Create</ButtonText>
                                        </Button>
                                    </ButtonGroup>
                                </AlertDialogFooter>
                            </AlertDialogContent>
                        </AlertDialog>

                        <View style={styles.container} $lg-display="flex" $lg-justifyContent="flex-start" $lg-marginLeft={"auto"} $lg-marginRight={"auto"}>
                            <ScrollView horizontal>
                                <View style={styles.listcontainer}>
                                    <View style={styles.listHeader}>
                                        <Text style={[styles.HeaderText, { width: 20, }]}>S.No</Text>
                                        <Text style={[styles.HeaderText, { width: 100, textAlign: "center" }]} $lg-w={"$2/5"}>Company Name</Text>
                                        <Text style={[styles.HeaderText, { width: 100, textAlign: "center" }]} $lg-w={"$2/5"}>Latitude</Text>
                                        <Text style={[styles.HeaderText, { width: 100, textAlign: "center" }]} $lg-w={"$2/5"}>Longitude</Text>
                                        <Text style={[styles.HeaderText, { width: 100, textAlign: "center" }]} $lg-w={"$2/5"}>Edit</Text>
                                        <Text style={[styles.HeaderText, { width: 100, textAlign: "center" }]} $lg-w={"$2/5"}>Delete</Text>
                                    </View>
                                    <FlatList
                                        data={validation}
                                        renderItem={rednerTableItem}
                                        style={{ borderWidth: 2, borderColor: "black" }}
                                    />
                                </View>
                            </ScrollView>

                        </View>

                    </View >





                    <Center bg="$error500">
                        <Spinner visible={spinner} />
                    </Center>



                    <Center>
                        <Modal
                            isOpen={openUpdateMoadl}
                            onClose={() => {
                                SetopenUpdateMoadl(false)
                            }}
                            finalFocusRef={ref}
                            size="lg"
                        >
                            <ModalBackdrop />
                            <ModalContent>
                                <ModalHeader>
                                    <Heading size="md">Edit Company Data</Heading>
                                    <ModalCloseButton>
                                        <Icon as={CloseIcon} />
                                    </ModalCloseButton>
                                </ModalHeader>
                                <ModalBody mt={"$5"}>

                                    <View >
                                        <FormControl minWidth='$80'>
                                            <FormControlLabel>
                                                <FormControlLabelText fontFamily="Inter_500Medium">
                                                    Company Name
                                                </FormControlLabelText>
                                            </FormControlLabel>
                                            <Input >
                                                <InputField value={Updateuserdata.companyname} defaultValue={Updateuserdata.companyname} onChangeText={(e) => SetUpdateuserdata({ ...Updateuserdata, companyname: e })} />
                                            </Input>
                                        </FormControl>


                                        <FormControl minWidth='$80' mt="$4">
                                            <FormControlLabel>
                                                <FormControlLabelText fontFamily="Inter_500Medium">
                                                    Latitude
                                                </FormControlLabelText>
                                            </FormControlLabel>
                                            <Input>
                                                <InputField value={Updateuserdata.latitude} defaultValue={Updateuserdata.latitude} onChangeText={(e) => SetUpdateuserdata({ ...Updateuserdata, latitude: e })} />
                                            </Input>
                                        </FormControl>

                                        <FormControl minWidth='$80' mt="$4">
                                            <FormControlLabel>
                                                <FormControlLabelText fontFamily="Inter_500Medium" >
                                                    Longitude
                                                </FormControlLabelText>
                                            </FormControlLabel>
                                            <Input>
                                                <InputField value={Updateuserdata.longitude} defaultValue={Updateuserdata.longitude} onChangeText={(e) => SetUpdateuserdata({ ...Updateuserdata, longitude: e })} />
                                            </Input>
                                        </FormControl>
                                        {/* 
                                <FormControl mt="$6">
                                    <Button bg="$darkBlue600" onPress={createcompany} style={{ display: loader === true ? "none" : "flex" }}>
                                        <ButtonText fontSize="$sm" fontWeight="$medium" fontFamily="Inter_500Medium">
                                            Create Company
                                        </ButtonText>
                                    </Button>

                                    <Button isDisabled={true} bg='$darkBlue600' width={"$full"} p='$3' style={{ display: loader === true ? "flex" : "none" }}>
                                        <ButtonSpinner mr='$1' />
                                        <ButtonText fontWeight='$medium' fontSize="$sm" fontFamily="Inter_500Medium">Please wait...</ButtonText>
                                    </Button>

                                </FormControl> */}


                                    </View>

                                </ModalBody>
                                <ModalFooter justifyContent="space-between">
                                    <Button
                                        variant="outline"
                                        size="sm"
                                        action="secondary"
                                        mr="$3"
                                        onPress={() => {
                                            SetopenUpdateMoadl(false)
                                        }}
                                    >
                                        <ButtonText>Cancel</ButtonText>
                                    </Button>
                                    <Button
                                        size="sm"
                                        action="positive"
                                        borderWidth="$0"
                                        onPress={() => {
                                            SetopenUpdateMoadl(false)
                                            confirmUpdate()
                                        }}
                                    >
                                        <ButtonText>Edit Data</ButtonText>
                                    </Button>
                                </ModalFooter>
                            </ModalContent>
                        </Modal>
                    </Center>


                </ImageBackground>

            </View>
        </>

    );
}

export default CompanyMaster;



const styles = StyleSheet.create({
    container: {
        paddingVertical: 30,
        paddingHorizontal: 10,
        borderRadius: 2
    },
    listcontainer: {
        flex: 1
    },
    listHeader: {
        flexDirection: "row",
        paddingVertical: 10,
        paddingHorizontal: 0,
        borderBottomWidth: 1,
        borderBottomColor: "red",
        backgroundColor: 'gray'

    },
    HeaderText: {
        flex: 1,
        fontFamily: "Inter_500Medium",
        fontSize: 16,
        color: "black",
        flexDirection: "row",
    },
    row: {
        flexDirection: "row",
        justifyContent: "space-around",
        alignItems: "flex-start",
        marginVertical: 8,
        marginHorizontal: 1,
        elevation: 1,
        borderRadius: 1,
        paddingVertical: 10,
        paddingHorizontal: 6

    },
    cell: {
        flex: 1,
        fontFamily: "Inter_500Medium",
        fontSize: 15,
        color: "#fff"
    }

});