import { Text, View, Card, Heading, Avatar, AvatarFallbackText, AvatarImage } from "@gluestack-ui/themed"
import { ImageBackground } from '@gluestack-ui/themed';

import backgroundimg from '../assets/bg/2d-graphic-colorful-wallpaper-with-grainy-gradients.jpg'

const DashBoard = () => {
    return (
        <>
            <ImageBackground source={backgroundimg}
                style={{ flex: 1, justifyContent: "center", backfaceVisibility: "visible" }} alt="background" h={"$full"}>

                <View style={{ flex: 1 }} height={"$full"}>

                    <View style={{ display: 'flex', flexDirection: "row", flexWrap: "wrap" }} $lg-m="$10" $lg-gap="$20">

                        <Card variant="outline" bg="$info400" m="$3" w="$96" style={{ display: "flex", flexDirection: "row", justifyContent: "space-between" }} $lg-w="$80" $xl-w="$96">
                            <View p={"$0"} m="0">
                                <Heading mb="$1" size="md" fontFamily="Inter_500Medium" p={"$0"}>
                                    Employees
                                </Heading>

                                <View paddingLeft="$16" mt={"$3"}>

                                    <Avatar bgColor="$warmGray800" size="lg" borderRadius="$full" >
                                        <AvatarFallbackText>Sandeep Srivastava</AvatarFallbackText>
                                    </Avatar>
                                </View>
                            </View>
                            <View >
                                <Avatar bgColor="$orange600" size="xl">
                                    <AvatarFallbackText>SS</AvatarFallbackText>
                                    <AvatarImage
                                        alt="user-image"
                                        source={{
                                            uri: "https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?ixlib=rb-4.0.3&ixid=MnwxMjA3fDB8MHxzZWFyY2h8Mnx8dXNlcnxlbnwwfHwwfHw%3D&auto=format&fit=crop&w=800&q=60",

                                        }}
                                    />
                                </Avatar>


                            </View>

                        </Card>


                        <Card variant="outline" bg="$green400" m="$3" w="$96" style={{ display: "flex", flexDirection: "row", justifyContent: "space-between" }} $lg-w="$80" $xl-w="$96">
                            <View p={"$0"} m="0">
                                <Heading mb="$1" size="md" fontFamily="Inter_500Medium" p={"$0"} >
                                    Present
                                </Heading>

                                <View paddingLeft="$16" mt={"$3"}>

                                    <Avatar bgColor="$warmGray800" size="lg" borderRadius="$full" >
                                        <AvatarFallbackText>Sandeep Srivastava</AvatarFallbackText>
                                    </Avatar>
                                </View>
                            </View>
                            <View >
                                <Avatar bgColor="$borderLight900" size="xl">
                                    <AvatarFallbackText>SS</AvatarFallbackText>
                                    <AvatarImage
                                        alt="user-image"
                                        source={{
                                            uri: "https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?ixlib=rb-4.0.3&ixid=MnwxMjA3fDB8MHxzZWFyY2h8Mnx8dXNlcnxlbnwwfHwwfHw%3D&auto=format&fit=crop&w=800&q=60",
                                        }}
                                        size="xs"
                                    />
                                </Avatar>


                            </View>

                        </Card>


                        <Card variant="outline" bg="$rose700" m="$3" w="$96" style={{ display: "flex", flexDirection: "row", justifyContent: "space-between" }} $lg-w="$80" $xl-w="$96">
                            <View p={"$0"} m="0">
                                <Heading mb="$1" size="md" fontFamily="Inter_500Medium" p={"$0"}>
                                    Absent
                                </Heading>

                                <View paddingLeft="$16" mt={"$3"}>

                                    <Avatar bgColor="$warmGray800" size="lg" borderRadius="$full" >
                                        <AvatarFallbackText>Sandeep Srivastava</AvatarFallbackText>
                                    </Avatar>
                                </View>
                            </View>
                            <View >
                                <Avatar bgColor="$orange600" size="xl">
                                    <AvatarFallbackText>SS</AvatarFallbackText>
                                    <AvatarImage
                                        alt="user-image"
                                        source={{
                                            uri: "https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?ixlib=rb-4.0.3&ixid=MnwxMjA3fDB8MHxzZWFyY2h8Mnx8dXNlcnxlbnwwfHwwfHw%3D&auto=format&fit=crop&w=800&q=60",

                                        }}
                                    />
                                </Avatar>


                            </View>

                        </Card>
                    </View>


                </View>
            </ImageBackground >
        </>
    );
}

export default DashBoard;