import { Avatar, View, AvatarFallbackText, VStack, HStack, Text, Heading, AvatarImage } from "@gluestack-ui/themed";
import { DrawerContentScrollView, DrawerItem } from '@react-navigation/drawer';
import { useNavigation } from '@react-navigation/native';
import { StyleSheet } from 'react-native';
import { MaterialIcons } from '@expo/vector-icons';

const DrawerList = [
    { icon: 'dashboard', label: 'DashBoard', navigateTo: 'DashBoard', role: 'admin' },
    { icon: 'calendar-month', label: 'Attendance', navigateTo: 'Attendance', role: 'user' },
    { icon: 'note', label: 'Report', navigateTo: 'Report', role: 'admin' },
    { icon: 'account-circle', label: 'User Register', navigateTo: 'account', role: 'admin' },
    { icon: 'account-circle', label: 'Company Location', navigateTo: 'CompanyMaster', role: 'admin' },
    { icon: 'logout', label: 'Logout', navigateTo: 'Logout' },
];

const DrawerLayout = ({ icon, label, navigateTo }) => {
    const navigation = useNavigation();
    return (
        <DrawerItem
            icon={({ color, size }) => <MaterialIcons name={icon} color={color} size={size} />}
            label={label}
            onPress={() => { navigation.navigate(navigateTo) }}
            style={styles.links}
        />
    );
}


const UserProfile = () => {
    return (
        <VStack space="2xl">
            <HStack space="md">
                <Avatar >
                    <AvatarFallbackText>SS</AvatarFallbackText>
                    <AvatarImage
                        source={{
                            uri: 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?ixlib=rb-4.0.3&ixid=MnwxMjA3fDB8MHxzZWFyY2h8Mnx8dXNlcnxlbnwwfHwwfHw%3D&auto=format&fit=crop&w=800&q=60',
                        }}
                    />
                </Avatar>
                <VStack>
                    <Heading size="sm" fontFamily="Inter_500Medium" >Ronald Richards</Heading>
                    <Text size="sm" fontFamily="Inter_500Medium">Nursing Assistant</Text>
                </VStack>
            </HStack>
        </VStack>
    )
}



const DrawerContent = ({ userdata }) => {

   // const { userdata } = route.params;

    console.log(userdata);

    const filteredDrawerList = DrawerList.filter(item => {
        // Filter out items based on user role
        return item.role === 'admin' ? userdata === 'admin' : true;
    });

    return (
        <>
            <View style={{ flex: 1 }}>
                <DrawerContentScrollView>
                    <View paddingLeft={"$2"} marginTop={"$5"}>
                        <UserProfile />
                    </View>

                    <View p={"$1"} marginTop={"$10"}>
                        {/* Render filtered drawer items */}
                        {filteredDrawerList.map((item, index) => (
                            <DrawerLayout
                                key={index}
                                icon={item.icon}
                                label={item.label}
                                navigateTo={item.navigateTo}
                            />
                        ))}
                    </View>
                </DrawerContentScrollView>
            </View>
        </>
    );
};



const styles = StyleSheet.create({
    links: {
        color: "red",
        fontSize: '20px',
        fontWeight: 'bold',
        fontFamily: "Inter_500Medium"
    }
})


export default DrawerContent;
