import React, { useState, useEffect } from 'react';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { config } from '@gluestack-ui/config';
import { GluestackUIProvider, StatusBar } from '@gluestack-ui/themed';
import { NavigationContainer } from '@react-navigation/native';
import 'react-native-reanimated';
import DrawerNavigator from './Navigation/DrawerNavigator';
import Login from './Components/Login';
import { createStackNavigator } from '@react-navigation/stack';



import { useFonts } from 'expo-font';

import { AppState } from 'react-native';
import { clearStorage, handleAppStateChange } from './Components/storageUtils'



import {
  Inter_400Regular,
  Inter_500Medium,
  Inter_600SemiBold,
  Inter_700Bold,
  Inter_900Black,
} from "@expo-google-fonts/inter";

const Stack = createStackNavigator();

export default function App() {


  const [isLoggedIn, setIsLoggedIn] = useState(false);

  const [userrole, setuserrole] = useState('')


  // useEffect(() => {
  //   AppState.addEventListener('change', handleAppStateChange);

  //   return () => {
  //     AppState.removeEventListener('change', handleAppStateChange);
  //   };

  // }, []);

  // useEffect(() => {
  //   return () => {
  //     clearStorage();
  //   };
  // }, []);



  const checkAuthentication = async () => {
    const userToken = await AsyncStorage.getItem('userData');

    const localdata = JSON.parse(userToken)

    setIsLoggedIn(localdata === null ? false : true);

    setuserrole(localdata?.role || null)
  };


  useEffect(() => {
    checkAuthentication();

    const intervalLoop = () => {
      checkAuthentication();
    };

    const intervalId = setInterval(intervalLoop, 1000);

    return () => {
      checkAuthentication();
      clearInterval(intervalId);
    };
  }, []);

  console.log(isLoggedIn);

  const [loaded] = useFonts({
    Inter_400Regular,
    Inter_500Medium,
    Inter_600SemiBold,
    Inter_700Bold,
    Inter_900Black,
  })

  if (!loaded) {
    return null
  }


  return (
    <GluestackUIProvider config={config}>
      <NavigationContainer>
        <StatusBar backgroundColor="black" />
        <Stack.Navigator
          screenOptions={{
            cardStyle: {
              backgroundColor: "white",
              opacity: 1,
              height: "auto"
            }
          }}

        >
          {isLoggedIn ? (
            <Stack.Screen
              name="DrawerNavigator"
              component={DrawerNavigator}
              options={{ headerShown: false }}
              initialParams={{ role: userrole }}
            />
          ) : (
            <Stack.Screen
              name="Login"
              component={Login}
              options={{ headerShown: false }}
              initialParams={{ setIsLoggedIn: false }}
            />
          )}

          <Stack.Screen
            name="Firstlogin"
            component={Login}
            options={{ headerShown: false }}
            initialParams={{ setIsLoggedIn }}
          />
        </Stack.Navigator>
      </NavigationContainer>

    </GluestackUIProvider>
  );
}
