import { createDrawerNavigator } from '@react-navigation/drawer';
import Attendance from '../Components/Attendance';
import LogoutScreen from '../Components/LogoutScreen';
import DrawerContent from './DrawerContent';
import DashBoard from '../Components/DashBoard';
import Report from '../Components/Report';
import UserRegister from '../Components/UserRegister';
import { useEffect, useState } from 'react';

import { useIsFocused } from "@react-navigation/native";
import AsyncStorage from '@react-native-async-storage/async-storage';
import CompanyMaster from '../Components/CompanyMaster';



const Drawer = createDrawerNavigator();






const DrawerNavigator = ({ route }) => {

  const { role } = route.params;


  console.log(role);

  const focus = useIsFocused();






  return (
    <Drawer.Navigator
      drawerContent={() => <DrawerContent userdata={role} />}
    >
      {role && role === 'admin' && (
        <Drawer.Screen
          name="DashBoard"
          component={DashBoard}
          options={{
            sceneContainerStyle: {
              display: role === 'admin' ? "flex" : "none",
            }
          }}
        />
      )}


      {role && role === 'user' && (
        <Drawer.Screen name="Attendance" component={Attendance} />
      )}

      {role && role === 'admin' && (
        <Drawer.Screen name="Report" component={Report}
          options={{
            sceneContainerStyle: {
              display: role === 'admin' ? "flex" : "none"
            }
          }}
        />
      )}


      {role && role === 'admin' && (
        <Drawer.Screen name="account" component={UserRegister}
          options={{
            sceneContainerStyle: {
              display: role === 'admin' ? "flex" : "none"
            }
          }}
        />
      )}

      {role && role === 'admin' && (
        <Drawer.Screen name="CompanyMaster" component={CompanyMaster}
          options={{
            sceneContainerStyle: {
              display: role === 'admin' ? "flex" : "none"
            }
          }}
        />
      )}



      <Drawer.Screen name="Logout" component={LogoutScreen} />
    </Drawer.Navigator>

  );
};

export default DrawerNavigator;
