import { View, Box, VStack, Input, InputField, FormControl, FormControlLabel, FormControlLabelText, Button, ButtonText, ScrollView, Center } from "@gluestack-ui/themed";
import { useEffect, useState, useRef } from "react";
import {
    AlertDialog,
    AlertDialogBackdrop,
    AlertDialogContent,
    AlertDialogHeader,
    AlertDialogCloseButton,
    AlertDialogFooter,
    AlertDialogBody,
    Icon,
    CloseIcon,
    CheckCircleIcon,
    Heading,
    Text,
    ButtonGroup
} from "@gluestack-ui/themed"
import { useToast, Toast, ToastTitle, ToastDescription, Pressable, ButtonSpinner, AlertCircleIcon, CheckIcon } from '@gluestack-ui/themed';
import axios from "axios";
import config from "../config";
import { useIsFocused } from "@react-navigation/native";


import { Modal, ModalBackdrop, ModalContent, ModalHeader, ModalCloseButton, ModalBody, ModalFooter } from '@gluestack-ui/themed';

import { StyleSheet, FlatList } from "react-native";

import Spinner from 'react-native-loading-spinner-overlay'

import { ImageBackground } from '@gluestack-ui/themed';

import backgroundimg from '../assets/bg/2d-graphic-colorful-wallpaper-with-grainy-gradients.jpg'

const UserRegister = () => {

    const toast = useToast()
    const focus = useIsFocused();


    const [userdata, setuserdata] = useState({
        username: "",
        usercode: "",
        password: ""
    })

    const [Updateuserdata, SetUpdateuserdata] = useState({
        username: "",
        usercode: "",
        password: ""
    })

    const [validation, Setvalidation] = useState([])

    const [loader, setloader] = useState(false)

    const [spinner, setspinner] = useState(false)

    const [showAlertDialog, setShowAlertDialog] = useState(false)
    const [showAlterStatus, SetshowAlterStatus] = useState('')

    const createAccount = () => {
        if (userdata.username === '') {
            toast.show({
                placement: "top",
                render: ({ id }) => {
                    const toastId = "toast-" + id
                    return (
                        <Toast bg="$error500" nativeID={toastId}>
                            <Icon as={AlertCircleIcon} color="$white" mt="$1" mr="$3" />
                            <VStack space="xs">
                                <ToastTitle color="$textLight50" fontFamily="Inter_500Medium">
                                    User Name Empty
                                </ToastTitle>
                                <ToastDescription color="$textLight50" fontFamily="Inter_500Medium">
                                    Please Fill The Valid User Name
                                </ToastDescription>
                            </VStack>
                            <Pressable mt="$1" onPress={() => toast.close(id)}>
                                <Icon as={CloseIcon} color="$coolGray50" />
                            </Pressable>
                        </Toast>
                    )
                },
            })
            return
        }

        if (userdata.usercode === '') {
            toast.show({
                placement: "top",
                render: ({ id }) => {
                    const toastId = "toast-" + id
                    return (
                        <Toast bg="$error500" nativeID={toastId}>
                            <Icon as={AlertCircleIcon} color="$white" mt="$1" mr="$3" />
                            <VStack space="xs">
                                <ToastTitle color="$textLight50" fontFamily="Inter_500Medium">
                                    User Code Empty
                                </ToastTitle>
                                <ToastDescription color="$textLight50" fontFamily="Inter_500Medium">
                                    Please Fill The Valid User Code
                                </ToastDescription>
                            </VStack>
                            <Pressable mt="$1" onPress={() => toast.close(id)}>
                                <Icon as={CloseIcon} color="$coolGray50" />
                            </Pressable>
                        </Toast>
                    )
                },
            })
            return
        }


        if (userdata.password === '') {
            toast.show({
                placement: "top",
                render: ({ id }) => {
                    const toastId = "toast-" + id
                    return (
                        <Toast bg="$error500" nativeID={toastId}>
                            <Icon as={AlertCircleIcon} color="$white" mt="$1" mr="$3" />
                            <VStack space="xs">
                                <ToastTitle color="$textLight50">
                                    Enter Password
                                </ToastTitle>
                                <ToastDescription color="$textLight50">
                                    Please Fill The Valid User Password
                                </ToastDescription>
                            </VStack>
                            <Pressable mt="$1" onPress={() => toast.close(id)}>
                                <Icon as={CloseIcon} color="$coolGray50" />
                            </Pressable>
                        </Toast>
                    )
                },
            })
            return
        }



        const Isuserexits = validation.some(items =>
            userdata.username === items.username &&
            userdata.usercode === items.usercode &&
            userdata.password === items.password
        );

        if (Isuserexits) {
            toast.show({
                placement: "top",
                render: ({ id }) => {
                    const toastId = "toast-" + id
                    return (
                        <Toast bg="$error500" nativeID={toastId}>
                            <Icon as={AlertCircleIcon} color="$white" mt="$1" mr="$3" />
                            <VStack space="xs">
                                <ToastTitle color="$textLight50" fontFamily="Inter_500Medium">
                                    User Existing
                                </ToastTitle>
                                <ToastDescription color="$textLight50" fontFamily="Inter_500Medium">
                                    This User Account Is already Presented..!
                                </ToastDescription>
                            </VStack>
                            <Pressable mt="$1" onPress={() => toast.close(id)}>
                                <Icon as={CloseIcon} color="$coolGray50" />
                            </Pressable>
                        </Toast>
                    )
                },
            })
            return

        }


        setShowAlertDialog(true)
    }

    const confirmCreateaccount = async () => {

        try {

            setloader(true)

            const response = await axios.post(`${config.API_URL}/user-register`, userdata)

            if (response.data) {

                setuserdata({ ...userdata, usercode: '', username: '', password: '' })

                toast.show({
                    placement: "top",
                    render: ({ id }) => {
                        const toastId = "toast-" + id
                        return (
                            <Toast bg="$success700" nativeID={toastId}>
                                <Icon as={CheckIcon} color="$white" mt="$1" mr="$3" />
                                <VStack space="xs">
                                    <ToastTitle color="$textLight50" fontFamily="Inter_500Medium">
                                        User Register Successs
                                    </ToastTitle>
                                    <ToastDescription color="$textLight50" fontFamily="Inter_500Medium">
                                        Account Created SuccessFully ...!
                                    </ToastDescription>
                                </VStack>
                                <Pressable mt="$1" onPress={() => toast.close(id)}>
                                    <Icon as={CloseIcon} color="$coolGray50" />
                                </Pressable>
                            </Toast>
                        )
                    },
                })


                setloader(false)
            }

        } catch (err) {
            console.log(err)
            setloader(false)
        }
    }

    const fetchdata = async () => {
        const response = await axios.get(`${config.API_URL}/get-userdata`)

        if (response.data) {
            Setvalidation(response.data)
        }

    }


    const [openUpdateMoadl, SetopenUpdateMoadl] = useState(false)

    const ref = useRef(null)


    const rednerTableItem = ({ item, index }) => {
        return (
            <View style={styles.row}>

                <Text style={[styles.cell, { width: 45 }]} color="$light900">{index + 1}</Text>
                <Text style={[styles.cell, { width: 150, textAlign: "center", marginStart: 5 }]}>{item.username}</Text>
                <Text style={[styles.cell, { width: 150, textAlign: "center" }]} ml={"$10"}>{item.usercode}</Text>
                <Text style={[styles.cell, { width: 150, textAlign: "center" }]} >{item.password}</Text>

                <Button style={[styles.cell, { width: 150, margin: 2, textAlign: "center", marginLeft: 5 }]} onPress={() => hanldeupdate(item.userid)} ref={ref}>
                    <ButtonText>Edit</ButtonText>
                </Button>

                <Button style={[styles.cell, { width: 150, margin: 2, textAlign: "center", marginLeft: 15 }]} bg="$error500" onPress={() => hanldedelete(item.userid)}>
                    <ButtonText>Delete</ButtonText>
                </Button>

            </View >

        )
    }

    const [id, setid] = useState('')


    const hanldeupdate = (id) => {
        setid(id)
        SetshowAlterStatus('update')
        SetopenUpdateMoadl(true)
        editdata(id)
        setspinner(true)
    }

    const editdata = async (id) => {
        const respose = await axios.get(`${config.API_URL}/edit-userdata/` + id)
        if (respose.data) {
            const { usercode, password, username } = respose.data[0]
            SetUpdateuserdata({ ...Updateuserdata, username: username, usercode: usercode, password: password })
            setspinner(false)
        }

    }

    const confirmUpdate = async () => {

        try {
            const resposnse = await axios.put(`${config.API_URL}/update-userdata/${id}`, Updateuserdata)

            if (resposnse.status === 200) {
                fetchdata()
                return (
                    toast.show({
                        placement: "top",
                        render: ({ id }) => {
                            const toastId = "toast-" + id
                            return (
                                <Toast bg="$success700" nativeID={toastId}>
                                    <Icon as={CheckIcon} color="$white" mt="$1" mr="$3" />
                                    <VStack space="xs">
                                        <ToastTitle color="$textLight50" fontFamily="Inter_500Medium">
                                            Updated Successs
                                        </ToastTitle>
                                        <ToastDescription color="$textLight50" fontFamily="Inter_500Medium">
                                            Your Data Updated Succesfully...!
                                        </ToastDescription>
                                    </VStack>
                                    <Pressable mt="$1" onPress={() => toast.close(id)}>
                                        <Icon as={CloseIcon} color="$coolGray50" />
                                    </Pressable>
                                </Toast>
                            )
                        },
                    })
                )
            }

        } catch (err) {
            console.log(err);
        }

    }

    const hanldedelete = async (id) => {
        try {
            const response = await axios.delete(`${config.API_URL}/delete-useres/${id}`)
            if (response.status === 200) {
                fetchdata()
                return (
                    toast.show({
                        placement: "top",
                        render: ({ id }) => {
                            const toastId = "toast-" + id
                            return (
                                <Toast bg="$success700" nativeID={toastId}>
                                    <Icon as={CheckIcon} color="$white" mt="$1" mr="$3" />
                                    <VStack space="xs">
                                        <ToastTitle color="$textLight50" fontFamily="Inter_500Medium">
                                            Delete Successs
                                        </ToastTitle>
                                        <ToastDescription color="$textLight50" fontFamily="Inter_500Medium">
                                            Your Data Delete Succesfully...!
                                        </ToastDescription>
                                    </VStack>
                                    <Pressable mt="$1" onPress={() => toast.close(id)}>
                                        <Icon as={CloseIcon} color="$coolGray50" />
                                    </Pressable>
                                </Toast>
                            )
                        },
                    })
                )
            }

        } catch (err) {
            console.log(err);
        }

    }





    useEffect(() => {
        if (focus === true) {
            fetchdata()
        }


    }, [focus])

    return (
        <>

            <View h={"$full"} w={"$full"} >

                <ImageBackground source={backgroundimg}
                    style={{ flex: 1, justifyContent: "center", backfaceVisibility: "visible" }} alt="background" height={1000}>


                    <View style={{ flex: 1, alignContent: 'center', justifyContent: "flex-start" }} padding="0" height={"$full"} w="$full" $lg-display="flex" $lg-justifyContent="center" $lg-alignItems="center">

                        <Box h="$96" justifyContent="center" borderWidth={1} borderRadius={"$lg"} $lg-w={"$1/3"} marginTop={"$10"}>
                            <VStack space="lg" reversed={false} alignItems="center" $lg-p={"$2"}>

                                <View>
                                    <Text fontFamily="Inter_500Medium" fontSize="$xl">Create User Account</Text>
                                </View>

                                <View >
                                    <FormControl minWidth='$80'>
                                        <FormControlLabel>
                                            <FormControlLabelText fontFamily="Inter_500Medium">
                                                User Name
                                            </FormControlLabelText>
                                        </FormControlLabel>
                                        <Input >
                                            <InputField value={userdata.username} defaultValue={userdata.username} onChangeText={(e) => setuserdata({ ...userdata, username: e })} />
                                        </Input>
                                    </FormControl>


                                    <FormControl minWidth='$80' mt="$4">
                                        <FormControlLabel>
                                            <FormControlLabelText fontFamily="Inter_500Medium">
                                                User Code
                                            </FormControlLabelText>
                                        </FormControlLabel>
                                        <Input>
                                            <InputField value={userdata.usercode} defaultValue={userdata.usercode} onChangeText={(e) => setuserdata({ ...userdata, usercode: e })} />
                                        </Input>
                                    </FormControl>

                                    <FormControl minWidth='$80' mt="$4">
                                        <FormControlLabel>
                                            <FormControlLabelText fontFamily="Inter_500Medium" >
                                                Password
                                            </FormControlLabelText>
                                        </FormControlLabel>
                                        <Input>
                                            <InputField value={userdata.password} defaultValue={userdata.password} onChangeText={(e) => setuserdata({ ...userdata, password: e })} />
                                        </Input>
                                    </FormControl>

                                    <FormControl mt="$6">
                                        <Button bg="$darkBlue600" onPress={createAccount} style={{ display: loader === true ? "none" : "flex" }}>
                                            <ButtonText fontSize="$sm" fontWeight="$medium" fontFamily="Inter_500Medium">
                                                Create Account
                                            </ButtonText>
                                        </Button>

                                        <Button isDisabled={true} bg='$darkBlue600' width={"$full"} p='$3' style={{ display: loader === true ? "flex" : "none" }}>
                                            <ButtonSpinner mr='$1' />
                                            <ButtonText fontWeight='$medium' fontSize="$sm" fontFamily="Inter_500Medium">Please wait...</ButtonText>
                                        </Button>

                                    </FormControl>


                                </View>

                            </VStack>
                        </Box>

                        <AlertDialog
                            isOpen={showAlertDialog}
                            onClose={() => {
                                setShowAlertDialog(false)
                            }}
                        >
                            <AlertDialogBackdrop />
                            <AlertDialogContent>
                                <AlertDialogHeader>
                                    <Heading size="lg" fontFamily="Inter_500Medium">Create Account</Heading>
                                    <AlertDialogCloseButton>
                                        <Icon as={CloseIcon} />
                                    </AlertDialogCloseButton>
                                </AlertDialogHeader>
                                <AlertDialogBody>
                                    <Text size="sm" fontFamily="Inter_500Medium">
                                        Are you sure you want to Create This Account
                                    </Text>
                                </AlertDialogBody>
                                <AlertDialogFooter>
                                    <ButtonGroup space="lg">
                                        <Button
                                            variant="outline"
                                            action="secondary"
                                            onPress={() => {
                                                setShowAlertDialog(false)
                                            }}
                                        >
                                            <ButtonText fontFamily="Inter_500Medium">Cancel</ButtonText>
                                        </Button>
                                        <Button
                                            bg="$error600"
                                            action="negative"
                                            onPress={() => {
                                                confirmCreateaccount()
                                                setShowAlertDialog(false)

                                            }}
                                        >
                                            <ButtonText fontFamily="Inter_500Medium">Create</ButtonText>
                                        </Button>
                                    </ButtonGroup>
                                </AlertDialogFooter>
                            </AlertDialogContent>
                        </AlertDialog>



                        <View style={styles.container} $lg-display="flex" $lg-justifyContent="flex-end" $lg-marginLeft={"auto"} $lg-marginRight={"auto"}>
                            <ScrollView horizontal>
                                <View style={styles.listcontainer}>
                                    <View style={styles.listHeader}>
                                        <Text style={[styles.HeaderText, { width: 20, }]}>S.No</Text>
                                        <Text style={[styles.HeaderText, { width: 100, textAlign: "center" }]} $lg-w={"$2/5"}>User Name</Text>
                                        <Text style={[styles.HeaderText, { width: 100, textAlign: "center" }]} $lg-w={"$2/5"}>User Code</Text>
                                        <Text style={[styles.HeaderText, { width: 100, textAlign: "center" }]} $lg-w={"$2/5"}>Password</Text>
                                        <Text style={[styles.HeaderText, { width: 100, textAlign: "center" }]} $lg-w={"$2/5"}>Edit</Text>
                                        <Text style={[styles.HeaderText, { width: 100, textAlign: "center" }]} $lg-w={"$2/5"}>Delete</Text>
                                    </View>
                                    <FlatList
                                        data={validation}
                                        renderItem={rednerTableItem}
                                        style={{ borderWidth: 2, borderColor: "black" }}
                                    />
                                </View>
                            </ScrollView>

                        </View>

                    </View >






                    <Center bg="$error500">
                        <Spinner visible={spinner} />
                    </Center>



                    <Center>
                        <Modal
                            isOpen={openUpdateMoadl}
                            onClose={() => {
                                SetopenUpdateMoadl(false)
                            }}
                            finalFocusRef={ref}
                            size="lg"
                        >
                            <ModalBackdrop />
                            <ModalContent>
                                <ModalHeader>
                                    <Heading size="md">Edit Company Data</Heading>
                                    <ModalCloseButton>
                                        <Icon as={CloseIcon} />
                                    </ModalCloseButton>
                                </ModalHeader>
                                <ModalBody mt={"$5"}>

                                    <View >
                                        <FormControl minWidth='$80'>
                                            <FormControlLabel>
                                                <FormControlLabelText fontFamily="Inter_500Medium">
                                                    User Name
                                                </FormControlLabelText>
                                            </FormControlLabel>
                                            <Input >
                                                <InputField value={Updateuserdata.username} defaultValue={Updateuserdata.username} onChangeText={(e) => SetUpdateuserdata({ ...Updateuserdata, username: e })} />
                                            </Input>
                                        </FormControl>


                                        <FormControl minWidth='$80' mt="$4">
                                            <FormControlLabel>
                                                <FormControlLabelText fontFamily="Inter_500Medium">
                                                    Latitude
                                                </FormControlLabelText>
                                            </FormControlLabel>
                                            <Input>
                                                <InputField value={Updateuserdata.usercode} defaultValue={Updateuserdata.usercode} onChangeText={(e) => SetUpdateuserdata({ ...Updateuserdata, usercode: e })} />
                                            </Input>
                                        </FormControl>

                                        <FormControl minWidth='$80' mt="$4">
                                            <FormControlLabel>
                                                <FormControlLabelText fontFamily="Inter_500Medium" >
                                                    Longitude
                                                </FormControlLabelText>
                                            </FormControlLabel>
                                            <Input>
                                                <InputField value={Updateuserdata.password} defaultValue={Updateuserdata.password} onChangeText={(e) => SetUpdateuserdata({ ...Updateuserdata, password: e })} />
                                            </Input>
                                        </FormControl>
                                        {/* 
                                <FormControl mt="$6">
                                    <Button bg="$darkBlue600" onPress={createcompany} style={{ display: loader === true ? "none" : "flex" }}>
                                        <ButtonText fontSize="$sm" fontWeight="$medium" fontFamily="Inter_500Medium">
                                            Create Company
                                        </ButtonText>
                                    </Button>

                                    <Button isDisabled={true} bg='$darkBlue600' width={"$full"} p='$3' style={{ display: loader === true ? "flex" : "none" }}>
                                        <ButtonSpinner mr='$1' />
                                        <ButtonText fontWeight='$medium' fontSize="$sm" fontFamily="Inter_500Medium">Please wait...</ButtonText>
                                    </Button>

                                </FormControl> */}


                                    </View>

                                </ModalBody>
                                <ModalFooter justifyContent="space-between">
                                    <Button
                                        variant="outline"
                                        size="sm"
                                        action="secondary"
                                        mr="$3"
                                        onPress={() => {
                                            SetopenUpdateMoadl(false)
                                        }}
                                    >
                                        <ButtonText>Cancel</ButtonText>
                                    </Button>
                                    <Button
                                        size="sm"
                                        action="positive"
                                        borderWidth="$0"
                                        onPress={() => {
                                            SetopenUpdateMoadl(false)
                                            confirmUpdate()
                                        }}
                                    >
                                        <ButtonText>Edit Data</ButtonText>
                                    </Button>
                                </ModalFooter>
                            </ModalContent>
                        </Modal>
                    </Center>
                </ImageBackground>
            </View >
        </>
    );
}

export default UserRegister;

const styles = StyleSheet.create({
    container: {
        paddingVertical: 30,
        paddingHorizontal: 10,
        borderRadius: 2
    },
    listcontainer: {
        flex: 1
    },
    listHeader: {
        flexDirection: "row",
        paddingVertical: 10,
        paddingHorizontal: 0,
        borderBottomWidth: 1,
        borderBottomColor: "red",
        backgroundColor: 'gray'

    },
    HeaderText: {
        flex: 1,
        fontFamily: "Inter_500Medium",
        fontSize: 16,
        color: "black",
        flexDirection: "row",
    },
    row: {
        flexDirection: "row",
        justifyContent: "space-around",
        alignItems: "flex-start",
        marginVertical: 8,
        marginHorizontal: 1,
        elevation: 1,
        borderRadius: 1,
        paddingVertical: 10,
        paddingHorizontal: 6,
        color: "#fff"

    },
    cell: {
        flex: 1,
        fontFamily: "Inter_500Medium",
        fontSize: 15,
        color: "#fff"
    }

});